sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader backdrop;
uniform float4 screen;
uniform float scale;
uniform float magnify;
uniform float sampling;
half4 main(float2 coord) {
    float2 c = size * 0.5;
    float2 p = c + (coord - c) / max(scale, 0.01);
    half m = image.eval(magnify > 0.5 ? p : coord).a;
    if (m <= 0.0) return half4(0.0);
    if (sampling < 0.5) p = screen.xy + floor(p - screen.xy) + 0.5;
    return backdrop.eval(p) * m;
}
